    internal static void av1_set_default_ref_deltas(Ptr<sbyte> ref_deltas)
    {
        Debug.Assert(!ref_deltas.IsNull);

        ref_deltas[INTRA_FRAME] = 1;
        ref_deltas[LAST_FRAME] = 0;
        ref_deltas[LAST2_FRAME] = ref_deltas[LAST_FRAME];
        ref_deltas[LAST3_FRAME] = ref_deltas[LAST_FRAME];
        ref_deltas[BWDREF_FRAME] = ref_deltas[LAST_FRAME];
        ref_deltas[GOLDEN_FRAME] = -1;
        ref_deltas[ALTREF2_FRAME] = -1;
        ref_deltas[ALTREF_FRAME] = -1;
    }

    internal static void av1_set_default_mode_deltas(Ptr<sbyte> mode_deltas)
    {
        Debug.Assert(!mode_deltas.IsNull);

        mode_deltas[0] = 0;
        mode_deltas[1] = 0;
    }

    private static void set_default_lf_deltas(loopfilter lf)
    {
        lf.mode_ref_delta_enabled = 1;
        lf.mode_ref_delta_update = 1;

        av1_set_default_ref_deltas(lf.ref_deltas);
        av1_set_default_mode_deltas(lf.mode_deltas);
    }

    internal static void av1_setup_frame_contexts(AV1_COMMON cm)
    {
        // Store the frame context into a special slot (not associated with any
        // reference buffer), so that we can set up cm->pre_fc correctly later
        // This function must ONLY be called when cm->fc has been initialized with
        // default probs, either by av1_setup_past_independence or after manually
        // initializing them
        cm.default_frame_context.CopyFrom(cm.fc);
        // [subset] cm->tiles.large_scale (large-scale tile decoding) is decoder-only: it is
        // always 0 in the encoder, so the copy into the reference buffers never runs.
        Debug.Assert(cm.tiles.large_scale == 0);
    }

    internal static void av1_setup_past_independence(AV1_COMMON cm)
    {
        // Reset the segment feature data to the default stats:
        // Features disabled, 0, with delta coding (Default state).
        av1_clearall_segfeatures(cm.seg);

        if (!cm.cur_frame.seg_map.IsNull)
        {
            memset(cm.cur_frame.seg_map, (byte)0,
                   (cm.cur_frame.mi_rows * cm.cur_frame.mi_cols));
        }

        // reset mode ref deltas
        av1_set_default_ref_deltas(cm.cur_frame.ref_deltas);
        av1_set_default_mode_deltas(cm.cur_frame.mode_deltas);
        set_default_lf_deltas(cm.lf);

        av1_default_coef_probs(cm);
        av1_init_mode_probs(cm.fc);
        av1_init_mv_probs(cm);
        cm.fc.initialized = 1;
        av1_setup_frame_contexts(cm);
    }
}
